class TextStats:
    def __init__(self, text):
        self.text = text

    def words(self):
        return len(self.text.split())

    def chars(self):
        return len(self.text.replace(" ", ""))

    def most_common(self):
        words = self.text.lower().split()
        return max(words, key=words.count)

