class Range2:
    def __init__(self, start, stop):
        self.start = start
        self.stop = stop

    def __iter__(self):
        current = self.start
        while current < self.stop:
            yield current
            current += 1

    def __len__(self):
        return max(0, self.stop - self.start)

    def __contains__(self, x):
        return self.start <= x < self.stop

