class UserFactory:
    def __init__(self):
        self.counter = 0

    def create(self, **overrides):
        self.counter += 1
        n = self.counter
        user = {"id": n, "name": f"user_{n}", "email": f"user_{n}@test.ru", "active": True}
        user.update(overrides)
        return user

    def create_many(self, n):
        return [self.create() for _ in range(n)]

